void basic_string::assign(const basic_string& str, size_type pos, size_type n) {
    // Check source boundaries
    if (pos > str._M_length) _M_throw_out_of_range();

    size_type count = std::min(n, str._M_length - pos);

    // Dynamic memory check: Do we need a bigger buffer?
    if (count > _M_capacity()) {
        _M_reallocate(count); // Allocate new buffer, update capacity
    } else if (count < _M_length && _M_is_sso()) {
        // Handle shrink when using SSO
    }

    // Copy the substring data
    std::copy(str._M_data() + pos, str._M_data() + pos + count, _M_data());

    _M_set_length(count);
}
